// Kinetic: base-jumping page script (generated by kinetic-tools/build/build.py)
(function () {
  const PAGE = {
    key: "base-jumping",
    v1: "Physics: nailed it 🪂",
    b1: "You've got the physics of low height, slow openings, wind and glide. Knowing why the margins are thin is the point of this page. It isn't training, and it doesn't make anyone ready to jump.",
    b2: "You have the basics. Fill the gaps below, especially the seconds-and-height chapter and the terrain margin: they explain most of the deaths in the studies.",
    b3: "No shame in that: this is exactly what the chapters are for. Read the ones linked below, then take the challenge again.",
    whereLabel: "Rules and events abroad →",
    whereHref: "#abroad",
    disclaimer: "<strong>Self-check only.</strong> This quiz is a learning aid. It is not a certification or training, and a high score does not mean anyone is ready to BASE jump or fly a wingsuit. Both sit far outside the beginner frame and come only after extensive skydiving experience and expert training."
  };
  const CHAPTERS = {
    "ch-seconds":   "Ch 1 · Low exits: seconds, not minutes",
    "ch-pilot":     "Ch 2 · Opening slowly",
    "ch-heading":   "Ch 3 · Off-heading openings & object strike",
    "ch-wind":      "Ch 4 · Wind and rotors",
    "ch-glide":     "Ch 5 · Wingsuit glide",
    "ch-proximity": "Ch 6 · Proximity and terrain",
    "ch-canopy":    "Ch 7 · One canopy & the landing",
    "ch-human":     "Ch 8 · The human side"
  };
  const QUESTIONS = [
    { ch: "ch-seconds",
      q: "What do the letters in BASE stand for?",
      o: ["Bridge, altitude, speed and elevation", "Balloon, aircraft, skydive and exit", "Basic aerial safety exam", "Building, antenna, span (bridge) and earth (cliff)"], a: 3,
      e: "BASE names the four kinds of fixed object people jump from: building, antenna, span (a bridge, arch or dome) and earth (a cliff)." },
    { ch: "ch-seconds",
      q: "How high above the landing area do BASE jumps often start, according to the 2013 study?",
      o: ["Over 3,000 m", "About 1,500 m", "Often less than 152 m (500 ft)", "Always exactly 300 m"], a: 2,
      e: "The study notes jumps start from \"much lower altitudes than skydives, often less than 152.4 m (500 feet) above the landing area\"." },
    { ch: "ch-seconds",
      q: "In our model, about how far does a jumper fall in the first 3 seconds?",
      o: ["About 5 m", "About 42 m", "About 150 m", "About 340 m"], a: 1,
      e: "Starting from rest, with drag: about 42 m in 3 s, reaching 96 km/h, half of terminal speed." },
    { ch: "ch-seconds",
      q: "Roughly how long does it take to reach 95% of terminal speed (about 193 km/h) in the model?",
      o: ["About 10 seconds and 340 m of height", "3 seconds", "1 second", "It's instant"], a: 0,
      e: "The speed-up phase is long: about 10 s and 340 m. Many BASE jumps don't have that much height at all." },
    { ch: "ch-pilot",
      q: "At half of terminal speed, how hard does the pilot chute pull compared with at full speed?",
      o: ["Half as hard", "Twice as hard", "The same", "A quarter as hard"], a: 3,
      e: "Drag grows with speed squared: (0.5)² = 0.25. Slow air means a weak pull and a slower opening." },
    { ch: "ch-pilot",
      q: "Why can a wingsuit make the pilot chute's job harder?",
      o: ["Wingsuits are heavier", "A burble of turbulent air above and behind the flyer can starve the pilot chute of air", "Wingsuits have no container", "The pilot chute is bigger"], a: 1,
      e: "USPA warns of the burble behind a wingsuit, and the 2013 study describes a burble catching a pilot chute and delaying or preventing the opening." },
    { ch: "ch-heading",
      q: "What does the 2013 study call the leading cause of serious injury and death in BASE jumping?",
      o: ["Cold", "Equipment theft", "Object strike: hitting the object jumped from", "Dehydration"], a: 2,
      e: "A single canopy that opens badly or faces the wrong way can fly into the cliff or building: \"object strike\"." },
    { ch: "ch-heading",
      q: "A canopy opens facing a cliff 10 m away and flies at 10 m/s. Roughly how long until it reaches the rock?",
      o: ["About 1 second", "About 10 seconds", "About 1 minute", "It can't reach it"], a: 0,
      e: "Time = gap ÷ speed = 10 ÷ 10 = 1 s. Example speed, but the point holds: there's almost no time." },
    { ch: "ch-wind",
      q: "A canopy flies at 10 m/s toward a cliff with a 4 m/s wind behind it. What's its speed over the ground?",
      o: ["6 m/s", "10 m/s", "40 m/s", "14 m/s"], a: 3,
      e: "Ground speed = airspeed + wind when the wind is behind you: 10 + 4 = 14 m/s toward the rock." },
    { ch: "ch-wind",
      q: "If a gust doubles in speed, how much harder does it push on a canopy?",
      o: ["The same", "Twice as hard", "Four times as hard", "Eight times as hard"], a: 2,
      e: "Wind force grows with speed squared: 2² = 4." },
    { ch: "ch-glide",
      q: "A wingsuit flies 100 km/h forward at a glide ratio of 2.5. How fast is it sinking?",
      o: ["About 4 km/h", "About 40 km/h", "About 100 km/h", "About 250 km/h"], a: 1,
      e: "Sink speed = forward speed ÷ glide ratio = 100 ÷ 2.5 = 40 km/h, the figure reported in the 2023 review." },
    { ch: "ch-glide",
      q: "In a steady glide in still air, the glide ratio equals what?",
      o: ["The lift-to-drag ratio", "Mass ÷ wing area", "Speed ÷ altitude", "Air density"], a: 0,
      e: "Forward distance ÷ height lost = lift ÷ drag. More lift for the same drag means a flatter glide." },
    { ch: "ch-proximity",
      q: "A suit loses 400 m of height per km. The slope below drops 364 m per km (20°). What happens to the gap?",
      o: ["It grows by 764 m per km", "It grows by 36 m per km", "It stays the same", "It shrinks by about 36 m per km"], a: 3,
      e: "364 − 400 = −36 m per km. A 50 m gap would be gone in about 1.4 km, roughly 50 seconds." },
    { ch: "ch-proximity",
      q: "In the 2013 study of 39 wingsuit BASE deaths, what share were cliff strikes?",
      o: ["About 5%", "About half (19 of 39, 49%)", "About 20%", "All of them"], a: 1,
      e: "19 (49%) were cliff strikes and 18 (46%) ground impacts; 17 of the 39 were attributed to flight-path miscalculation." },
    { ch: "ch-canopy",
      q: "How many main parachutes does a BASE jumper usually carry, per the 2013 study?",
      o: ["One, with no reserve", "Two, like a skydiver", "Three", "None"], a: 0,
      e: "The study describes \"the single canopy used in BASE jumping (no reserve chute)\". Low jumps rarely leave time to use a second one." }
  ];

  // ---------- QUIZ RENDER ----------
  const list = document.getElementById("quiz-list");
  const dots = document.getElementById("quiz-dots");
  const prog = document.getElementById("quiz-progress");
  const progLabel = document.getElementById("quiz-progress-label");
  const warn = document.getElementById("quiz-warn");
  const resultBox = document.getElementById("quiz-result");
  let graded = false;

  function esc(s) { return s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  QUESTIONS.forEach((item, i) => {
    const n = i + 1;
    const div = document.createElement("div");
    div.className = "q";
    div.id = "q" + n;
    div.dataset.index = i;
    div.innerHTML =
      `<span class="qtag">${esc(CHAPTERS[item.ch].split(" · ")[1])}</span>` +
      `<span class="qnum">Question ${n} / ${QUESTIONS.length}</span>` +
      `<h3>${esc(item.q)}</h3>` +
      `<div class="opts" role="radiogroup" aria-label="Question ${n}">` +
      item.o.map((opt, j) =>
        `<label class="opt"><input type="radio" name="q${n}" value="${j}"><span>${esc(opt)}</span><span class="mark"></span></label>`
      ).join("") +
      `</div><div class="explain" aria-live="polite"></div>`;
    list.appendChild(div);

    const d = document.createElement("a");
    d.href = "#q" + n; d.textContent = n; d.id = "dot" + n;
    d.setAttribute("aria-label", "Go to question " + n);
    dots.appendChild(d);
  });

  function answeredCount() {
    return QUESTIONS.filter((_, i) => document.querySelector(`input[name="q${i + 1}"]:checked`)).length;
  }
  function updateProgress() {
    const c = answeredCount();
    prog.style.width = (c / QUESTIONS.length * 100) + "%";
    progLabel.textContent = `${c} of ${QUESTIONS.length} answered`;
  }

  list.addEventListener("change", (ev) => {
    if (graded || ev.target.type !== "radio") return;
    const q = ev.target.closest(".q");
    q.querySelectorAll(".opt").forEach(l => l.classList.toggle("sel", l.querySelector("input").checked));
    document.getElementById("dot" + (+q.dataset.index + 1)).classList.add("answered");
    updateProgress();
    warn.style.display = "none";
  });

  function grade() {
    const unanswered = QUESTIONS.length - answeredCount();
    if (unanswered > 0 && !document.getElementById("quiz-submit").dataset.confirmed) {
      warn.textContent = `${unanswered} question${unanswered > 1 ? "s" : ""} unanswered. They'll count as wrong. Press submit again to score anyway.`;
      warn.style.display = "block";
      document.getElementById("quiz-submit").dataset.confirmed = "1";
      return;
    }
    graded = true;
    let score = 0;
    const wrongChapters = new Map();
    QUESTIONS.forEach((item, i) => {
      const n = i + 1;
      const qEl = document.getElementById("q" + n);
      const picked = document.querySelector(`input[name="q${n}"]:checked`);
      const pickedIdx = picked ? +picked.value : -1;
      const right = pickedIdx === item.a;
      if (right) score++;
      else wrongChapters.set(item.ch, (wrongChapters.get(item.ch) || []).concat(n));
      qEl.classList.add("graded", right ? "right" : (picked ? "wrong" : "skipped"));
      qEl.querySelectorAll("input").forEach(inp => inp.disabled = true);
      qEl.querySelectorAll(".opt").forEach((lab, j) => {
        if (j === item.a) { lab.classList.add("correct"); lab.querySelector(".mark").textContent = "✓ correct"; }
        else if (j === pickedIdx) { lab.classList.add("incorrect"); lab.querySelector(".mark").textContent = "✗ your pick"; }
      });
      const ex = qEl.querySelector(".explain");
      ex.innerHTML = `<span class="verdict">${right ? "Correct." : (picked ? "Not quite." : "Skipped.")}</span> ${esc(item.e)}` +
        (right ? "" : `<br><a class="chlink" href="#${item.ch}" data-wrong-link="${item.ch}">Read ${esc(CHAPTERS[item.ch])} →</a>`);
      const dot = document.getElementById("dot" + n);
      dot.classList.remove("answered"); dot.classList.add(right ? "right" : "wrong");
    });

    const pct = score / QUESTIONS.length;
    let lvl, title, blurb;
    if (pct >= 0.8) { lvl = "lvl-ready"; title = PAGE.v1; blurb = PAGE.b1; }
    else if (pct >= 0.55) { lvl = "lvl-close"; title = "Nearly there. Brush up on a couple of chapters"; blurb = PAGE.b2; }
    else { lvl = "lvl-brush"; title = "Brush up first"; blurb = PAGE.b3; }

    resultBox.className = "result show " + lvl;
    const chItems = [...wrongChapters.entries()].map(([ch, qs]) =>
      `<li><a href="#${ch}" data-summary-link="${ch}">${esc(CHAPTERS[ch])}</a> <span class="small">(question${qs.length > 1 ? "s" : ""} ${qs.join(", ")})</span></li>`).join("");
    resultBox.innerHTML =
      `<div class="score" id="quiz-score">${score}<small> / ${QUESTIONS.length}</small></div>` +
      `<h3 id="quiz-verdict">${title}</h3><p>${blurb}</p>` +
      `<div class="result-note" id="quiz-disclaimer" role="note" data-reel-hide>${PAGE.disclaimer}</div>` +
      (chItems ? `<strong>Chapters to read:</strong><ul id="quiz-revisit">${chItems}</ul>` : `<p><strong>Perfect score.</strong> The chapters still have the worked numbers if you want to go deeper.</p>`) +
      `<div class="actions"><button class="btn btn-ghost" type="button" id="quiz-retake">↺ Retake the challenge</button><a class="btn btn-ghost" href="${PAGE.whereHref || "#where"}">${PAGE.whereLabel}</a></div>`;
    document.getElementById("quiz-retake").addEventListener("click", resetQuiz);
    document.getElementById("quiz-submit").style.display = "none";
    warn.style.display = "none";
    resultBox.scrollIntoView({ behavior: "smooth", block: "start" });
    try { localStorage.setItem("kinetic-" + PAGE.key + "-last", JSON.stringify({ score, of: QUESTIONS.length, at: Date.now() })); } catch (e) {}
  }

  function resetQuiz() {
    graded = false;
    resultBox.className = "result"; resultBox.innerHTML = "";
    document.querySelectorAll(".q").forEach(q => {
      q.className = "q";
      q.querySelector(".explain").innerHTML = "";
      q.querySelectorAll("input").forEach(i => { i.checked = false; i.disabled = false; });
      q.querySelectorAll(".opt").forEach(l => { l.className = "opt"; l.querySelector(".mark").textContent = ""; });
    });
    document.querySelectorAll("#quiz-dots a").forEach(d => d.className = "");
    const sub = document.getElementById("quiz-submit");
    sub.style.display = ""; delete sub.dataset.confirmed;
    updateProgress();
    document.getElementById("q1").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("quiz-submit").addEventListener("click", grade);
  document.getElementById("quiz-reset").addEventListener("click", resetQuiz);
  updateProgress();

  // Expose for automated tests
  window.KINETIC_QUIZ = { QUESTIONS, CHAPTERS, grade, resetQuiz };


  // ---------- MARGIN LAB (BASE & wingsuit) ----------
  // Freefall from rest with quadratic drag: v_t = √(2mg ÷ (ρ CdA)), m 90 kg, ρ 1.1, CdA 0.559 (same as the skydiving page).
  // h(t) = (v_t²/g)·ln cosh(gt/v_t); v(t) = v_t·tanh(gt/v_t); time to fall H = (v_t/g)·acosh(exp(Hg/v_t²)).
  // Opening: steady slow-down from pull speed to 5 m/s over the chosen time → height = (v + 5)/2 × T. Illustrative only.
  // Wingsuit: still air, forward 100 km/h; sink = 100/GR; angle = atan(1/GR); margin change per km = 1000·(tan θ − 1/GR).
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("bj-h")) return;
    const g = 9.81, vt = Math.sqrt(2 * 90 * g / (1.1 * 0.559));
    let T = 3;
    const fmt = n => Math.round(n).toLocaleString("en-US");
    const fall = t => vt * vt / g * Math.log(Math.cosh(g * t / vt));
    function update() {
      const H = +$("bj-h").value, d = +$("bj-d").value;
      $("bj-h-o").textContent = fmt(H) + " m";
      $("bj-d-o").textContent = d.toFixed(1) + " s";
      $("bj-fall").textContent = (vt / g * Math.acosh(Math.exp(H * g / (vt * vt)))).toFixed(1) + " s";
      const lost = fall(d), v = vt * Math.tanh(g * d / vt);
      if (lost >= H) {
        $("bj-lost").textContent = "all of it"; $("bj-v").textContent = "—"; $("bj-pct").textContent = "ground before the pull";
        $("bj-drag").textContent = "—"; $("bj-open").textContent = "—"; $("bj-left").textContent = "none: ground first";
        $("bj-bar").style.width = "100%";
      } else {
        const op = (v + 5) / 2 * T, left = H - lost - op;
        $("bj-lost").textContent = fmt(lost) + " m";
        $("bj-v").textContent = fmt(v * 3.6) + " km/h";
        $("bj-pct").textContent = Math.round(v / vt * 100) + "% of terminal speed";
        $("bj-drag").textContent = Math.round(Math.pow(v / vt, 2) * 100) + "%";
        $("bj-open").textContent = fmt(op) + " m";
        $("bj-left").textContent = left > 0 ? fmt(left) + " m" : "none: ground first";
        $("bj-bar").style.width = Math.min(100, (lost + op) / H * 100) + "%";
      }
      const gr = +$("bj-gr").value, sl = +$("bj-sl").value, c = +$("bj-c").value;
      $("bj-gr-o").textContent = gr.toFixed(1) + " : 1";
      $("bj-sl-o").textContent = sl + "°";
      $("bj-c-o").textContent = fmt(c) + " m";
      const per = 1000 * (Math.tan(sl * Math.PI / 180) - 1 / gr);
      $("bj-ang").textContent = (Math.atan(1 / gr) * 180 / Math.PI).toFixed(1) + "°";
      $("bj-vz").textContent = fmt(100 / gr) + " km/h";
      $("bj-loss").textContent = fmt(1000 / gr) + " m";
      $("bj-km").textContent = (per >= 0 ? "+" : "−") + fmt(Math.abs(per)) + " m";
      if (per < 0) {
        const km = c / -per;
        $("bj-zero").textContent = km < 1 ? fmt(km * 1000) + " m" : km.toFixed(2) + " km";
        $("bj-t").textContent = "≈ " + fmt(km * 36) + " s at 100 km/h";
      } else { $("bj-zero").textContent = "never: it grows"; $("bj-t").textContent = "in still air, on this slope"; }
    }
    ["bj-h", "bj-d", "bj-gr", "bj-sl", "bj-c"].forEach(id => $(id).addEventListener("input", update));
    document.querySelectorAll("#bj-o button").forEach(b => b.addEventListener("click", () => {
      T = +b.dataset.v;
      document.querySelectorAll("#bj-o button").forEach(x => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
      update();
    }));
    update();
  })();

  // ---------- LEVEL TABS ----------
  const tabs = document.querySelectorAll(".lvl-tabs button");
  tabs.forEach(btn => btn.addEventListener("click", () => {
    tabs.forEach(b => b.setAttribute("aria-selected", b === btn ? "true" : "false"));
    document.querySelectorAll(".lvl-panel").forEach(p => p.classList.toggle("show", p.id === btn.getAttribute("aria-controls")));
  }));
  // a link or URL hash to #lvl-x opens that tab (and scrolls to the tabs), even after the visitor switched tabs
  const openLvl = (hash, scroll) => {
    const btn = /^#lvl-[\w-]+$/.test(hash || "") && [...tabs].find(b => "#" + b.getAttribute("aria-controls") === hash);
    if (!btn) return false;
    if (btn.getAttribute("aria-selected") !== "true") btn.click();
    if (scroll) { (btn.closest(".lvl-tabs") || btn).scrollIntoView({ block: "start" }); btn.focus({ preventScroll: true }); }
    return true;
  };
  document.addEventListener("click", e => {
    const a = e.target.closest && e.target.closest('a[href^="#lvl-"]');
    if (a && openLvl(a.getAttribute("href"), true)) { e.preventDefault(); if (location.hash !== a.getAttribute("href")) history.pushState(null, "", a.getAttribute("href")); }
  });
  window.addEventListener("hashchange", () => openLvl(location.hash, true));
  openLvl(location.hash, true);

  // ---------- STICKY NAV ACTIVE STATE ----------
  const navLinks = [...document.querySelectorAll(".sectionnav a[href^='#']")];
  const targets = navLinks.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          navLinks.forEach(a => a.classList.toggle("active", a.getAttribute("href") === "#" + en.target.id));
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    targets.forEach(t => io.observe(t));
  }

  // ---------- MOBILE NAV: edge fades + keep the active link in view ----------
  (function () {
    const snav = document.querySelector(".sectionnav");
    if (!snav) return;
    const fades = () => {
      const max = snav.scrollWidth - snav.clientWidth;
      snav.classList.toggle("fade-l", max > 4 && snav.scrollLeft > 4);
      snav.classList.toggle("fade-r", max > 4 && snav.scrollLeft < max - 4);
    };
    snav.addEventListener("scroll", fades, { passive: true });
    window.addEventListener("resize", fades);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fades);
    fades();
    const keep = () => {
      const a = snav.querySelector("a.active");
      if (!a || snav.scrollWidth <= snav.clientWidth + 4) return;
      const r = a.getBoundingClientRect(), n = snav.getBoundingClientRect();
      if (r.left < n.left + 16 || r.right > n.right - 40) snav.scrollBy({ left: r.left - n.left - 20, behavior: "smooth" });
    };
    if ("MutationObserver" in window) {
      const mo = new MutationObserver(keep);
      snav.querySelectorAll("a").forEach(a => mo.observe(a, { attributes: true, attributeFilter: ["class"] }));
    }
  })();
})();
